/// its error, and `work` with no root is `.`, canonicalized.
fn labeled_repos(
    scope: &Scope,
    root: Option<&Path>,
) -> Result<Vec<(String, PathBuf)>, Box<dyn std::error::Error>> {
    let paths = common::scope_to_repos(scope, root)?;
    scope
        .0
        .iter()
        .zip(paths)
        .map(|(side, path)| {
